**Key Store Methods (useProgressiveStore — extensions)**
```typescript
export const useProgressiveStore = create<ProgressiveStoreState & ProgressiveStoreMethods>(
  (set, get) => ({
    // ... existing

    // Chart interactions
    setChartState: (state: Partial<VoyageChartState>) => set(s => ({
      chartState: { ...s.chartState, ...state }
    })),

    toggleChartOverlay: (layer: 'assumptions' | 'risks' | 'ancestry') => set(s => {
      const overlays = new Set(s.chartState.overlays);
      overlays.has(layer) ? overlays.delete(layer) : overlays.add(layer);
      return { chartState: { ...s.chartState, overlays } };
    }),

    // Assumption verification
    markAssumptionVerified: (assumptionId: string, verified: boolean) => {
      // Find assumption in current checkpoint's snapshot, update it, trigger context-chain refresh
      set(s => ({
        sessions: s.sessions.map(sess =>
          sess.id === s.currentSessionId ? {
            ...sess,
            checkpoints: sess.checkpoints.map(cp => ({
              ...cp,
              state_snapshot: {
                ...cp.state_snapshot,
                hidden_assumptions: cp.state_snapshot?.hidden_assumptions?.map(a =>
                  a.id === assumptionId ? { ...a, verified } : a
                ) || [],
              }
            }))
          } : sess
        )
      }));
    }
  })
);
```

