export async function exportChartAsPNG(
  svg: SVGElement,
  overlays: Set<string>,
  projectName: string
): Promise<Blob> {
  const canvas = await html2canvas(svg, {
    backgroundColor: 'var(--surface)',
    scale: 2, // High-res
    useCORS: true,
  });
  canvas.toBlob(blob => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${projectName}-voyage-chart-${new Date().toISOString().split('T')[0]}.png`;
    a.click();
  });
}
```

