### 2. Brief 2.0: Voyage Narrative (component: OutputBrief.tsx)
**Replaces current static markdown generation.** Structure: 4-act narrative.

```tsx
export function OutputBrief({ session, project }: Props) {
  // Act 1: DEPARTURE — original question + reframing hypothesis
  // Act 2: OBSTACLES — what rehearsal revealed (risks, blind spots)
  // Act 3: COURSE CORRECTION — how planning evolved (refinement loops, assumption validation)
  // Act 4: ITHACA — final strategy, governing idea, governing assumption, success metric

  return (
    <div className="space-y-8 max-w-3xl">
      <Act1Departure decompose={decompose} recast={recast} />
      <Act2Obstacles rehearsal={rehearsal} risks={classifiedRisks} />
      <Act3Correction refinement={refinement} assumptionDeltas={assumptionUpdates} />
      <Act4Ithaca recast={recast} project={project} />
    </div>
  );
}

// Each act is a collapsible section with inline provenance anchors
function Act1Departure({ decompose, recast }: Props) {
  return (
    <section>
      <h2 className="text-2xl font-serif text-[var(--text-primary)]">⚓ 출항: 우리는 어디로 가는가</h2>
      <div className="space-y-4 mt-4 text-[15px] leading-relaxed">
        <p>
          <strong>표면 과제</strong>{' '}
          <SourceLink phase="decompose" field="surface_task" label="(어디서 온 질문?)">
            {decompose.analysis.surface_task}
          </SourceLink>
        </p>
        <p>
          <strong>진짜 질문</strong>{' '}
          <SourceLink phase="decompose" field="reframed_question" label="(왜 재정의했나?)">
            {decompose.selected_question}
          </SourceLink>
        </p>
        <p className="text-[14px] text-[var(--text-secondary)] italic">
          {decompose.analysis.why_reframing_matters}
        </p>

        {/* Hidden assumptions as expandable list with status badges */}
        <div className="mt-4 space-y-2">
          <p className="font-semibold text-[13px] uppercase text-[var(--text-tertiary)]">⚠ 검증 필요한 전제</p>
          {decompose.analysis.hidden_assumptions.map((a, i) => (
            <div key={i} className="flex items-start gap-2 p-2 rounded bg-[var(--accent)]/5">
              <AssumptionBadge assumption={a} />
              <span className="flex-1">{a.assumption}</span>
              <SourceLink phase="decompose" field={`hidden_assumptions.${i}`} />
            </div>
          ))}
        </div>
      </div>
