  );
}

// SourceLink component: hoverable anchor showing journey
function SourceLink({ phase, field, label, children }: Props) {
  const [showProvenance, setShowProvenance] = useState(false);
  const chain = getProvenanceChain(field, phase);

  return (
    <span className="relative inline-block group">
      <button 
        className="underline decoration-dotted decoration-[var(--accent)]/50 hover:decoration-[var(--accent)]"
        onClick={() => setShowProvenance(!showProvenance)}
        title={`See why this was chosen (${phase})`}
      >
        {children}{label && <span className="text-[11px] text-[var(--accent)] ml-1">{label}</span>}
      </button>
      {showProvenance && (
        <ProvenanceTooltip chain={chain} />
      )}
    </span>
  );
}
```

