// Assumption graph: each node is an assumption, edges show dependencies
function AssumptionDependencyGraph({ assumptions, steps, risks }: Props) {
  return (
    <div className="rounded-lg border border-[var(--border-subtle)] p-6 bg-[var(--surface)]">
      <h3 className="text-[14px] font-bold text-[var(--text-primary)] mb-4">🗺 전제 의존성</h3>

      {assumptions.map((assumption, i) => {
        const validatedBy = steps.filter(s => 
          s.task.includes(assumption.assumption.substring(0, 10))
        );
        const failureRisk = risks.find(r => r.text.includes(assumption.assumption.substring(0, 20)));

        return (
          <div key={i} className="mb-4 p-3 rounded border border-[var(--border-subtle)] relative">
            {/* Assumption node with status */}
            <div className="flex items-start gap-2">
              <AssumptionStatusBadge 
                verified={assumption.verified}
                risksIfFalse={assumption.risk_if_false}
              />
              <div className="flex-1">
                <p className="text-[13px] font-semibold text-[var(--text-primary)]">{assumption.assumption}</p>
                {assumption.risk_if_false && (
                  <p className="text-[12px] text-red-600 mt-1">
                    ⚠ 틀리면: {assumption.risk_if_false}
                  </p>
                )}
              </div>
            </div>

            {/* Links to validating steps */}
            {validatedBy.length > 0 && (
              <div className="mt-2 ml-6 text-[11px] text-[var(--text-secondary)]">
                ✓ 검증 단계: {validatedBy.map((s, j) => <span key={j}>{s.task}</span>).reduce((a, b) => <>{a}, {b}</>, null)}
              </div>
            )}

            {/* Failure scenario from rehearsal */}
            {failureRisk && (
              <div className="mt-2 ml-6 p-2 bg-[#E24B4A]/10 rounded text-[11px] text-[#E24B4A]">
                🔴 {failureRisk.text}
                <SourceLink phase="rehearsal" label=" (인터뷰)" />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
