```typescript
// When generating outputs, store provenance metadata
interface OutputGeneration {
  outputType: 'brief' | 'prompt' | 'spec' | 'checklist';
  fields: AttributedOutputField[];
  generatedAt: string;
  sessionId: string;
  projectId: string;
}

// Store alongside outputs in Supabase table `output_generations`
// On output updates (refinement, assumption validation), track deltas:
interface OutputDelta {
  fieldId: string;
  before: string;
  after: string;
  causedBy: {
    phase: 'refinement' | 'assumption_validation' | 'risk_addressed';
    sourceId: string;
  };
  timestamp: string;
}

// When user clicks "Copy" or "Export", append provenance summary
function exportWithProvenance(output: AttributedOutputField[], includeHistory: boolean): string {
  const mainContent = renderFields(output);
  if (includeHistory) {
    const history = buildProvenanceFootnotes(output);
    return mainContent + '\n\n---\n\n## 결정 과정 (Decision Trail)\n' + history;
  }
  return mainContent;
}
