## 4. Execution Checklist 2.0: Live, Synced, Feedback-Driven

### Supabase-Backed Checklist Component (new file: ChecklistLive.tsx)

```tsx
'use client';

import { useState, useEffect } from 'react';
import { useSupabase } from '@/lib/supabase';

interface ChecklistItem {
  id: string;
  step_num: number;
  title: string;
  type: 'execution' | 'checkpoint' | 'assumption_validation';
  checked: boolean;
  assumption_validated?: boolean;
  assumption_id?: string;
  abort_triggered?: boolean;
  completed_at?: string;
  notes?: string;
}

export function ChecklistLive({ projectId }: { projectId: string }) {
  const { supabase } = useSupabase();
  const [items, setItems] = useState<ChecklistItem[]>([]);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');

  // Real-time updates from Supabase
  useEffect(() => {
    const subscription = supabase
      .from('checklist_items')
      .on('*', payload => {
        if (payload.new) {
          setItems(prev => [...prev.filter(i => i.id !== payload.new.id), payload.new]);
        }
      })
      .subscribe();

    return () => subscription.unsubscribe();
  }, []);

  // When assumption validation step is completed, check for abort condition
  const handleCheckItem = async (itemId: string, checked: boolean, notes?: string) => {
    setSyncStatus('syncing');

    const item = items.find(i => i.id === itemId);
    if (item?.type === 'assumption_validation') {
      // User just validated/invalidated an assumption
      const validated = checked; // simplified: checked = assumption confirmed

      if (!validated && item.assumption_id) {
        // Assumption FAILED — trigger abort
        await supabase.from('checklist_items').update({
          abort_triggered: true,
          completed_at: new Date().toISOString(),
          notes: `Assumption "${item.assumption_id}" not validated. Abort recommended. ${notes || ''}`
        }).eq('id', itemId);

        // Notify user + disable dependent steps
        alert(`⚠ Assumption "${item.assumption_id}" could not be validated. Steps 3-5 are now blocked pending reassessment.`);
      }
    }

    await supabase.from('checklist_items').update({
      checked,
      completed_at: checked ? new Date().toISOString() : null,
      notes
    }).eq('id', itemId);

    setSyncStatus('synced');
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h3 className="font-bold">실행 체크리스트</h3>
        <span className={`text-[11px] ${syncStatus === 'synced' ? 'text-green-600' : 'text-amber-600'}`}>
          {syncStatus === 'synced' ? '✓ 동기화됨' : syncStatus === 'syncing' ? '⟳ 동기화 중...' : '⚠ 오류'}
        </span>
      </div>

      <div className="space-y-2">
        {items.map((item, idx) => (
          <div
            key={item.id}
            className={`flex items-start gap-3 p-3 rounded-lg border ${
              item.abort_triggered ? 'bg-red-50 border-red-300' :
              item.checked ? 'bg-green-50 border-green-200' :
              'bg-white border-gray-200'
            }`}
          >
            <input
              type="checkbox"
              checked={item.checked}
              onChange={(e) => handleCheckItem(item.id, e.target.checked)}
              disabled={item.abort_triggered}
              className="mt-1 cursor-pointer"
            />
            <div className="flex-1">
              <p className={`text-[14px] font-medium ${item.checked ? 'line-through text-gray-500' : ''}`}>
                Step {item.step_num}: {item.title}
              </p>
              {item.type === 'assumption_validation' && (
                <p className="text-[12px] text-gray-600 mt-1">
                  🎯 Validates assumption: <code className="bg-gray-100 px-1">{item.assumption_id}</code>
                </p>
              )}
              {item.notes && (
                <p className="text-[12px] text-gray-700 mt-2 italic">
                  📝 {item.notes}
                </p>
              )}
            </div>
            {item.abort_triggered && (
              <div className="text-[12px] font-bold text-red-600 whitespace-nowrap">
                ⚠ ABORT
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
```

