## Component Specs

### Step Container (Container.tsx)
\`\`\`tsx
export function StepContainer({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="py-8 md:py-12">
      <h1 className="text-display font-serif mb-12 text-[var(--text-primary)]">{title}</h1>
      <div className="max-w-2xl space-y-8">
        {children}
      </div>
    </div>
  );
}
\`\`\`

**Spacing logic:**
- Title has 48px bottom margin (not 24px) — creates breathing room
- Content sections space by 32px (lg), not 16-24px
- Card padding: 24px (not 16-20px)
- No card shadows by default; only on `data-interactive="true"` with --shadow-sm

### Card Surface (Card.tsx)
\`\`\`tsx
interface CardProps {
  className?: string;
  interactive?: boolean;
  children: React.ReactNode;
}

export function Card({ className, interactive, children }: CardProps) {
  return (
    <div
      className={cn(
        'bg-[var(--surface)] border border-[var(--border-subtle)] rounded-lg p-6',
        'transition-shadow duration-300 ease-spring',
        interactive && 'hover:shadow-sm cursor-pointer',
        className
      )}
    >
      {children}
    </div>
  );
}
\`\`\`

**Concrete rules:**
- Default: flat (no shadow), 1px border --border-subtle
- Hover state (interactive=true only): --shadow-sm added
- Padding always 24px
- Border radius always 20px (--radius-lg)
- Max padding on internal block elements: 16px (internal breathing)

### Button System (Button.tsx)
\`\`\`tsx
type Variant = 'primary' | 'secondary' | 'text';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}

export function Button({ variant = 'primary', size = 'md', className, ...props }: ButtonProps) {
  const sizeClass = {
    sm: 'px-3 py-1.5 text-11px font-medium',
    md: 'px-5 py-2.5 text-13px font-semibold',
    lg: 'px-6 py-3 text-14px font-semibold',
  }[size];

  const variantClass = {
    primary: 'bg-[var(--text-primary)] text-[var(--bg)] hover:shadow-md active:shadow-xs',
    secondary: 'bg-[var(--surface)] border-1 border-[var(--border)] text-[var(--text-primary)] hover:bg-[var(--bg)]',
    text: 'bg-transparent text-[var(--text-primary)] hover:underline',
  }[variant];

  return (
    <button
      className={cn(
        'rounded-lg transition-all duration-250 ease-spring focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)]',
        sizeClass,
        variantClass,
        className
      )}
      {...props}
    />
  );
}
\`\`\`

**Concrete rules:**
- Primary: solid dark background, full shadow on hover only
- Secondary: surface bg + subtle border, no shadow
- Text: transparent, underline on hover (no background change)
- All transitions 250ms ease-spring
- Padding minimum 12px horizontal (generous tap targets)
- No icon-only buttons (add text label or use aria-label)

### Input Field (Input.tsx)
\`\`\`tsx
export function Input({
  label,
  error,
  ...props
}: React.InputHTMLAttributes<HTMLInputElement> & {
  label?: string;
  error?: string;
}) {
  return (
    <div className="flex flex-col gap-2">
      {label && (
        <label className="text-label text-[var(--text-secondary)]">
          {label}
        </label>
      )}
      <input
        className={cn(
          'w-full px-4 py-3 rounded-lg border-1.5 border-[var(--border)]',
          'bg-[var(--surface)] text-[var(--text-primary)]',
          'placeholder:text-[var(--text-tertiary)]',
          'focus:border-[var(--accent)] focus:outline-none',
          'transition-colors duration-200 ease-spring',
          error && 'border-[var(--danger)]'
        )}
        {...props}
      />
      {error && <p className="text-11px text-[var(--danger)]">{error}</p>}
    </div>
  );
}
\`\`\`

**Concrete rules:**
- Padding: 12px horizontal, 12px vertical (32px height minimum on mobile, 28px desktop)
- Border: 1.5px (visual weight, not fussy)
- No box-shadow on focus (outline only via --accent border)
- Transition: 200ms (faster than general 250ms, more immediate)

### Wayfinding Strip (StepNav.tsx)
\`\`\`tsx
const STEPS = [
  { id: 'reframe', label: '문제 재정의', number: '01' },
  { id: 'recast', label: '실행 설계', number: '02' },
  { id: 'rehearse', label: '사전 검증', number: '03' },
  { id: 'refine', label: '수정 반영', number: '04' },
];

export function StepNav({ active, onStepChange }: { active: string; onStepChange: (id: string) => void }) {
  return (
    <nav className="flex flex-col gap-6 py-8">
      {STEPS.map((step, i) => (
        <button
          key={step.id}
          onClick={() => onStepChange(step.id)}
          className={cn(
            'text-left transition-all duration-300 ease-spring',
            'border-l-2 pl-4 py-2',
            active === step.id
              ? 'border-[var(--accent)] text-[var(--text-primary)]'
              : 'border-[var(--border-subtle)] text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'
          )}
        >
          <div className="text-11px font-bold text-[var(--text-tertiary)] tracking-widest mb-1">
            STEP {step.number}
          </div>
          <div className="text-15px font-serif font-semibold text-[var(--text-primary)]">
            {step.label}
          </div>
        </button>
      ))}
    </nav>
  );
}
\`\`\`

**Concrete rules:**
- Left border (2px) animates color on active state
- Step numbers are always tertiary (de-emphasized)
- Labels use serif font (editorial weight)
- No underline or background on hover
- 6px gap between number and label
- Full height tap target (44px minimum on mobile)

