### 6. Backend Functions (src/lib/ or API)

```typescript
// src/lib/asset-indexing.ts
export async function indexVoyageAsAsset(session: ProgressiveSession, outcome?: OutcomeRecord) {
  // Extract problem domain via simple keyword matching or LLM
  const domain = detectDomain(session.problem_text);

  // Index all assumptions + outcomes
  const assumptions = session.snapshots?.flatMap(s => 
    s.hidden_assumptions || []
  ) ?? [];

  for (const a of assumptions) {
    await upsertLibraryEntry({
      assumption_text: a.assumption,
      domain,
      first_seen_in_voyage: session.id,
      validation_results: outcome ? {
        tested: 1,
        confirmed: outcome.hypothesis_result === 'confirmed' ? 1 : 0,
        refuted: outcome.hypothesis_result === 'refuted' ? 1 : 0,
      } : { tested: 0, confirmed: 0, refuted: 0 },
    });
  }

  // Tag session for search
  session.asset_tags = [{
    domain,
    problem_type: detectProblemType(session.problem_text),
    decision_pattern: '...', 
    has_outcome: !!outcome,
    outcome_result: outcome?.overall_success,
  }];
}

export async function searchSimilarVoyages(
  problemText: string, 
  userId: string,
  limit: number = 3
): Promise<RelatedVoyage[]> {
  // v1: keyword/regex match on domain + problem type
  // v2: semantic embedding (OpenAI embed → pgvector)

  const userSessions = await db.progressiveSession.findMany({
    where: { project_id: { in: userProjects.map(p => p.id) } },
    include: { checkpoints: true, waypoints: true },
  });

  return userSessions
    .map(s => ({
      ...s,
      score: computeSimilarity(problemText, s.problem_text),
    }))
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}

export async function getSmartDefaults(problemText: string, userId: string) {
  const bestMatch = await searchSimilarVoyages(problemText, userId, 1);
  if (!bestMatch?.[0]) return null;

  const source = bestMatch[0];

  return {
    voyage_id: source.id,
    voyage_name: source.project_name,
    similarity_score: computeSimilarity(problemText, source.problem_text),
    suggested_personas: extractPersonasFromCheckpoints(source.checkpoints),
    suggested_assumptions: extractAssumptionsFromCheckpoints(source.checkpoints),
    suggested_workflow_steps: extractStepsFromCheckpoints(source.checkpoints),
    outcome: source.outcome_status,
  };
}
